import {priceForOrder,sizeForOrder,pnlFor,tickStep} from './math.js';
const $=id=>document.getElementById(id), fmt=(v,d=2)=>Number.isFinite(+v)?Number(v).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}):'—';
let coin='BTC',testnet=false,price=0,displayPrice=0,lastQuote=0,meta=null,ctx=null,ws=null,reconnect=null,generation=0,address=null,provider=null,exchange=null,account=null,accountAt=0,side=true,busy=false,pending=null,toastTimer;
const base=()=>testnet?'https://api.hyperliquid-testnet.xyz':'https://api.hyperliquid.xyz';
const position=()=>account?.assetPositions?.find(x=>x.position.coin===coin)?.position;
const notify=m=>{$('toast').textContent=m;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,9000)};
async function info(body){const r=await fetch(base()+'/info',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('Hyperliquid 请求失败 ('+r.status+')');return r.json()}
function status(){const live=price>0&&Date.now()-lastQuote<15000;$('feed-status').textContent=live?'行情已连接':'行情连接中断';$('status-dot').style.background=live?'#9ce6cb':'#d6aa5b';renderOrder();return live}
function setContext(c){if(!c||!(+c.markPx>0))return;ctx=c;price=+c.markPx;lastQuote=Date.now();if(!displayPrice)displayPrice=price;$('top-price').textContent=fmt(price);$('hero-price').innerHTML=fmt(price)+'<small>USDC</small>';$('mark').textContent=fmt(price);let ch=(price/+c.prevDayPx-1)*100;$('change').textContent=Number.isFinite(ch)?(ch>=0?'+':'')+fmt(ch)+'%  / 24h':'24h —';$('change').className=ch>=0?'positive':'negative';$('volume').textContent=+c.dayNtlVlm>=1e6?fmt(+c.dayNtlVlm/1e6)+'M USDC':fmt(c.dayNtlVlm)+' USDC';$('funding').textContent=fmt(+c.funding*100,4)+'%';$('last-update').textContent='更新于 '+new Date().toLocaleTimeString('zh-CN',{hour12:false});status();renderPosition()}
async function marketSnapshot(g=generation){try{const data=await info({type:'metaAndAssetCtxs'});if(g!==generation)return;meta=data[0];const idx=meta.universe.findIndex(x=>x.name===coin&&!x.isDelisted);if(idx<0)throw Error('该市场在当前网络不可用');let max=meta.universe[idx].maxLeverage||20;$('leverage').max=max;$('max-leverage').textContent=max+'×';if(+$('leverage').value>max)$('leverage').value=max;setContext(data[1][idx])}catch(e){if(g===generation){$('feed-status').textContent='行情不可用 · 自动重连';status()}}}
function startSocket(g){clearTimeout(reconnect);if(ws){ws.onclose=null;ws.close()}ws=new WebSocket(base().replace('https:','wss:')+'/ws');const sock=ws;sock.onopen=()=>{if(g!==generation)return;sock.send(JSON.stringify({method:'subscribe',subscription:{type:'activeAssetCtx',coin}}))};sock.onmessage=e=>{if(g!==generation)return;try{const m=JSON.parse(e.data);if(m.channel==='activeAssetCtx'&&m.data.coin===coin)setContext(m.data.ctx)}catch{}};sock.onerror=()=>sock.close();sock.onclose=()=>{if(g===generation)reconnect=setTimeout(()=>startSocket(g),2000)}}
function resetMarket(){generation++;price=displayPrice=lastQuote=0;meta=ctx=null;$('top-price').textContent='—';$('hero-price').innerHTML='—<small>USDC</small>';for(const x of ['mark','change','volume','funding'])$(x).textContent='—';$('feed-status').textContent='连接行情中';$('last-update').textContent='等待 Hyperliquid 行情';marketSnapshot();startSocket(generation);renderPosition();renderOrder()}
async function refreshAccount(){if(!address)return;const a=address,g=generation;const data=await info({type:'clearinghouseState',user:a});if(a!==address||g!==generation)return;account=data;accountAt=Date.now();$('balance').textContent=fmt(data.withdrawable)+' USDC';$('equity').textContent=fmt(data.marginSummary.accountValue)+' USDC';let p=data.assetPositions.reduce((s,x)=>s+(+x.position.unrealizedPnl||0),0);$('account-pnl').textContent=(p>=0?'+':'')+fmt(p)+' USDC';$('account-pnl').className=p>=0?'positive':'negative';renderPosition();renderOrder()}
function clearAccount(){account=null;accountAt=0;for(const id of ['balance','equity','account-pnl'])$(id).textContent='— USDC';renderPosition();renderOrder()}
async function connect(){if(busy)return;if(address){address=null;exchange=null;clearAccount();$('connect').textContent='连接钱包 ↗';return}try{provider=window.ethereum;if(!provider)throw Error('请在已安装 MetaMask、Rabby 等钱包的浏览器中打开本站。');const accounts=await provider.request({method:'eth_requestAccounts'});if(!accounts[0])throw Error('未选择钱包账户');address=accounts[0];$('connect').textContent=address.slice(0,6)+'…'+address.slice(-4)+' ×';clearAccount();await refreshAccount();notify('钱包已连接 · '+(testnet?'测试网':'主网实盘'))}catch(e){notify(e.message)}}
async function getExchange(){if(exchange)return exchange;try{const [hl,viem]=await Promise.all([import('https://esm.sh/@nktkas/hyperliquid@0.33.3?bundle'),import('https://esm.sh/viem@2.37.3?bundle')]);const wallet=viem.createWalletClient({account:address,transport:viem.custom(provider)});exchange=new hl.ExchangeClient({transport:new hl.HttpTransport({isTestnet:testnet}),wallet});return exchange}catch{throw Error('交易签名组件加载失败，请检查网络后重试。')}}
function asset(){const index=meta?.universe.findIndex(x=>x.name===coin&&!x.isDelisted);if(index==null||index<0)throw Error('请等待市场信息加载');return {index,...meta.universe[index]}}
function renderOrder(){let amount=+$('amount').value,lev=+$('leverage').value;$('leverage-value').textContent=lev;$('margin').textContent=fmt(amount/lev)+' USDC';let sz=0;try{sz=sizeForOrder(amount,price,asset().szDecimals)}catch{}$('order-size').textContent=(sz>0?sz:'—')+' '+coin;const pos=position(),opposite=pos&&((+pos.szi>0)!==side);$('trade').className='trade-button '+(side?'buy':'sell');$('trade').textContent=busy?'正在处理…':!address?'连接钱包':opposite?'请先平掉反向持仓':(side?'开多 / 买入 ':'开空 / 卖出 ')+coin;$('trade').disabled=busy||!!(address&&(opposite||!account||Date.now()-accountAt>20000||Date.now()-lastQuote>15000||price<=0||sz<=0||amount<10));}
function renderPosition(){const p=position();$('position-count').textContent=p?'1':'0';if(!p){$('position-panel').innerHTML='<div class="empty-icon">≋</div><h3>'+(address?'当前交易对暂无持仓':'你的下一笔交易，从这里开始')+'</h3><p>'+(address?(account?'开多或开空，开仓价将标记在盘面上':'正在同步 Hyperliquid 账户…'):'连接钱包，查看 Hyperliquid 持仓与实时盈亏')+'</p>';return}const size=+p.szi,entry=+p.entryPx,profit=price?pnlFor(size,entry,price):+p.unrealizedPnl;const stale=Date.now()-accountAt>20000;const profitText=(profit>=0?'+':'')+fmt(profit);$('position-panel').innerHTML=`<div class="position-row"><div><small>合约 / 方向</small><b>${coin} <span class="${size>0?'positive':'negative'}">${size>0?'多':'空'} ${p.leverage.value}×</span></b></div><div><small>持仓数量</small><b>${Math.abs(size)} ${coin}</b></div><div><small>开仓均价</small><b>${fmt(entry)}</b></div><div><small>未实现盈亏 / USDC</small><b class="${profit>=0?'positive':'negative'}">${profitText}</b></div><div><small>预估强平价</small><b>${p.liquidationPx?fmt(p.liquidationPx):'—'}</b></div><div><button id="share">𝕏 分享</button> <button id="close" ${busy||stale?'disabled':''}>平仓</button></div></div><p class="position-warning">${stale?'账户同步延迟，请刷新后操作。':'盈亏按标记价格计算，未扣除手续费与资金费用。'}</p>`;$('close').onclick=()=>prepare(true);$('share').onclick=()=>{const text=`我在 AXIS 的 ${coin} 永续${size>0?'多':'空'}单\n开仓价：$${fmt(entry)}\n标记价：$${fmt(price)}\n未实现盈亏：${profitText} USDC（未扣费用）\n${testnet?'Hyperliquid 测试网':'Hyperliquid 主网'} · ${new Date().toISOString()}`;window.open('https://x.com/intent/tweet?text='+encodeURIComponent(text),'_blank','noopener,noreferrer')}}
async function prepare(close=false){if(!address)return connect();if(busy)return;try{if(!status())throw Error('行情已过期，请等待恢复后再下单');await refreshAccount();if(Date.now()-accountAt>20000)throw Error('请等待账户同步');const a=asset(),p=position(),buy=close?+p?.szi<0:side,size=close?Math.abs(+p?.szi):sizeForOrder(+$('amount').value,price,a.szDecimals);if(!size||!Number.isFinite(size))throw Error('下单数量无效');if(!close&&size*price<10)throw Error('订单名义金额不足 10 USDC，请提高金额');if(!close&&p&&((+p.szi>0)!==buy))throw Error('请先平掉反向持仓');pending={close,buy,size,coin,address,network:testnet,entry:p?.entryPx,positionSize:p?.szi,leverage:+$('leverage').value,asset:a.index,szDecimals:a.szDecimals};$('confirm-title').textContent=(close?'平仓':buy?'开多':'开空')+' '+coin;$('confirm-detail').textContent=`${testnet?'测试网':'主网 · 真实资金'}\n数量：${size} ${coin}\n预计名义金额：${fmt(size*price)} USDC\n${close?'只减仓：开启':'全仓杠杆：'+pending.leverage+'×'}\n最大滑点：0.5%`;$('confirm-submit').disabled=false;$('confirm-submit').textContent='签名并提交';$('confirm').showModal()}catch(e){notify(e.message)}}
function lock(v){busy=v;for(const id of ['network','coin','connect','long-tab','short-tab','amount','leverage'])$(id).disabled=v;renderOrder();renderPosition()}
async function execute(){const q=pending;if(!q||busy)return;lock(true);$('confirm-submit').disabled=true;let sent=false;try{const check=()=>{if(q.address!==address||q.network!==testnet||q.coin!==coin)throw Error('钱包或市场已改变，请重新确认');if(Date.now()-lastQuote>15000)throw Error('行情已过期，请重新确认')};check();const ex=await getExchange();await refreshAccount();check();if(!q.close&&position()&&((+position().szi>0)!==q.buy))throw Error('持仓方向已变化，请重新确认');if(q.close&&position()?.szi!==q.positionSize)throw Error('持仓已变化，请重新确认平仓数量');if(!q.close){await ex.updateLeverage({asset:q.asset,isCross:true,leverage:q.leverage});check()}const px=priceForOrder(price,q.buy,q.szDecimals);const cloid='0x'+Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join('');sent=true;const r=await ex.order({orders:[{a:q.asset,b:q.buy,p:px,s:String(q.size),r:q.close,t:{limit:{tif:'Ioc'}},c:cloid}],grouping:'na'});const s=r.response?.data?.statuses?.[0];if(s?.error)throw Error(s.error);if(s?.filled)notify(`已成交 ${s.filled.totalSz} ${coin}，均价 ${fmt(s.filled.avgPx)} USDC`);else notify('订单已返回，请核对持仓；未成交部分已取消。');$('confirm').close();await refreshAccount()}catch(e){notify((sent?'请先刷新持仓核对成交结果，勿重复提交。':'')+(e.shortMessage||e.message||'交易失败'));$('confirm').close()}finally{pending=null;lock(false)}}
$('connect').onclick=connect;$('coin').onchange=e=>{coin=e.target.value;resetMarket();refreshAccount().catch(()=>{})};$('network').onchange=e=>{testnet=e.target.value==='testnet';exchange=null;clearAccount();$('network-label').textContent=testnet?'测试网':'主网实盘';resetMarket();refreshAccount().catch(()=>{})};$('long-tab').onclick=()=>{side=true;$('long-tab').className='selected-long';$('short-tab').className='';renderOrder()};$('short-tab').onclick=()=>{side=false;$('short-tab').className='selected-short';$('long-tab').className='';renderOrder()};for(const id of ['amount','leverage'])$(id).oninput=renderOrder;document.querySelectorAll('[data-amount]').forEach(b=>b.onclick=()=>{if(busy)return;$('amount').value=b.dataset.amount;renderOrder()});$('trade').onclick=()=>prepare();$('refresh').onclick=async()=>{try{await refreshAccount();await marketSnapshot();notify(address?'账户与行情已刷新':'行情已刷新，请连接钱包查看持仓')}catch(e){notify(e.message)}};$('confirm-submit').onclick=execute;
if(window.ethereum?.on){window.ethereum.on('accountsChanged',()=>{address=null;exchange=null;clearAccount();$('connect').textContent='连接钱包 ↗';$('confirm').close();notify('钱包账户已变化，请重新连接')});window.ethereum.on('chainChanged',()=>{exchange=null})}
const canvas=$('gauge'),c=canvas.getContext('2d');let W=0,H=0;const resize=()=>{const box=$('chart').getBoundingClientRect();W=box.width;H=box.height;canvas.width=W*devicePixelRatio;canvas.height=H*devicePixelRatio;c.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0)};new ResizeObserver(resize).observe($('chart'));
function draw(){requestAnimationFrame(draw);if(!W||!H)return;c.clearRect(0,0,W,H);const axis=W-100,cy=H/2;c.strokeStyle='#1a242c';c.lineWidth=1;for(let x=32;x<axis;x+=70){c.beginPath();c.moveTo(x,0);c.lineTo(x,H-35);c.stroke()}c.fillStyle='#111920';c.fillRect(axis,0,100,H-35);c.strokeStyle='#28343e';c.beginPath();c.moveTo(axis,0);c.lineTo(axis,H-35);c.stroke();if(!price){c.fillStyle='#687782';c.font='13px sans-serif';c.textAlign='center';c.fillText('正在获取 Hyperliquid 实时价格…',axis/2,cy);return}displayPrice+=(price-displayPrice)*.09;let step=tickStep(price,+$('scale').value),spacing=54;let baseTick=Math.floor(displayPrice/step);c.font='12px ui-monospace, monospace';c.textAlign='right';for(let k=baseTick-10;k<=baseTick+10;k++){let val=k*step,y=cy+(displayPrice-val)/step*spacing;if(y<45||y>H-40)continue;c.strokeStyle='#1d2932';c.beginPath();c.moveTo(0,y);c.lineTo(axis,y);c.stroke();c.strokeStyle='#41505c';c.beginPath();c.moveTo(axis,y);c.lineTo(axis+10,y);c.stroke();c.fillStyle='#7b8c9a';c.fillText(fmt(val),W-12,y+4);for(let j=1;j<=4;j++){const sy=y+j*spacing/5;c.strokeStyle='#2b3a45';c.beginPath();c.moveTo(axis,sy);c.lineTo(axis+5,sy);c.stroke()}}
const p=position();if(p){const entry=+p.entryPx,raw=cy+(displayPrice-entry)/step*spacing,y=Math.max(155,Math.min(H-95,raw));const profit=pnlFor(+p.szi,entry,price);c.strokeStyle='#dbb67a';c.setLineDash([5,6]);c.beginPath();c.moveTo(24,y);c.lineTo(axis,y);c.stroke();c.setLineDash([]);c.fillStyle='#211f1b';c.fillRect(25,y-23,Math.min(370,axis-32),24);c.fillStyle='#e3c28e';c.textAlign='left';c.font='11px sans-serif';let off=raw!==y?(raw<y?'↑ ':'↓ '):'';c.fillText(off+'开仓 '+fmt(entry)+'  ·  '+(profit>=0?'+':'')+fmt(profit)+' USDC',34,y-7)}
c.strokeStyle='#88d8b8';c.lineWidth=1;c.beginPath();c.moveTo(0,cy);c.lineTo(W,cy);c.stroke();const x=axis/2;c.fillStyle='#91e5c61a';c.beginPath();c.arc(x,cy,17,0,Math.PI*2);c.fill();c.fillStyle='#9ce6cb';c.beginPath();c.arc(x,cy,5,0,Math.PI*2);c.fill();c.fillStyle='#9ce6cb';c.fillRect(axis-7,cy-15,107,30);c.fillStyle='#152b24';c.font='bold 12px ui-monospace, monospace';c.textAlign='right';c.fillText(fmt(price),W-10,cy+4)}
setInterval(()=>{if(ws?.readyState===1)ws.send(JSON.stringify({method:'ping'}))},25000);setInterval(()=>{status();renderPosition()},2000);setInterval(()=>marketSnapshot(),10000);setInterval(()=>refreshAccount().catch(()=>{}),5000);resetMarket();draw();
